insert into public.knowledge_sources (id, title, kind, original_document, checked_at, expected_count, notes, status) values ('catalogo-general-14', '14 destinos turísticos del Ecuador', 'catalog', 'CHULLA_VIDA_3_PAQUETE/catalogos/01_catalogo_14_destinos.txt', '2026-11-12'::date, 14, '["Los precios indicados son valores referenciales del catálogo y no representan tarifas oficiales de ingreso a los destinos ni paquetes comerciales verificados.","Las capacidades, duraciones y niveles de dificultad son parámetros de organización de las experiencias de Chulla Vida, pendientes de confirmación con los operadores correspondientes.","Antes de ofrecer una reserva, se deben confirmar disponibilidad, servicios incluidos, transporte, alimentación, alojamiento, tarifas vigentes y condiciones de seguridad."]'::jsonb, 'published') on conflict (id) do update set title = excluded.title, kind = excluded.kind, original_document = excluded.original_document, checked_at = excluded.checked_at, expected_count = excluded.expected_count, notes = excluded.notes, status = excluded.status;
insert into public.knowledge_sources (id, title, kind, original_document, checked_at, expected_count, notes, status) values ('catalogo-costa-7', 'Experiencias de la Costa', 'catalog', 'CHULLA_VIDA_3_PAQUETE/catalogos/03_costa_7_experiencias_extraido.txt', '2026-11-12'::date, 7, '["Fichas completas y tarifas propuestas por persona","Servicios prepagados · Transporte del visitante hasta el punto de encuentro no incluido.","Tarifas de venta estimadas, sujetas a confirmación con los operadores. No son cotizaciones ni reservas activas.","Tarifas propuestas · USD por persona | Noviembre de 2026","Precio y prestaciones sujetos a confirmación final por proveedor y fecha. Servicios no descritos se consideran excluidos."]'::jsonb, 'published') on conflict (id) do update set title = excluded.title, kind = excluded.kind, original_document = excluded.original_document, checked_at = excluded.checked_at, expected_count = excluded.expected_count, notes = excluded.notes, status = excluded.status;
insert into public.knowledge_sources (id, title, kind, original_document, checked_at, expected_count, notes, status) values ('catalogo-galapagos-12', '12 experiencias turísticas de las Islas Galápagos', 'catalog', 'CHULLA_VIDA_3_PAQUETE/catalogos/02_galapagos_12_experiencias.txt', '2026-11-12'::date, 12, '["Los precios indicados son valores referenciales encontrados en plataformas de reservas y sitios de operadores al 12 de noviembre de 2026. No representan tarifas oficiales de ingreso a los destinos ni paquetes comerciales verificados. Varían por temporada, operador y tamaño del grupo, y algunos están en euros.","Las capacidades, duraciones y niveles de dificultad son estimaciones basadas en las descripciones de cada tour, pendientes de confirmación con los operadores correspondientes.","Costos fijos de ingreso y traslado:","Tasa de ingreso al Parque Nacional Galápagos: $200 para extranjeros (menores de 12 años, $100) y $30 para ecuatorianos y residentes de 12 a 65 años. Menores de 2 años, exentos. Se paga en efectivo al llegar.","Tarjeta de Control de Tránsito (TCT): $20 por persona, en el aeropuerto de Quito o Guayaquil antes de embarcar.","Vuelo Quito–Galápagos, ida y vuelta: desde $223, mínimo reportado por la prensa en un feriado. Puede subir hasta $755.","Lancha entre islas (Santa Cruz, San Cristóbal, Isabela): $30 por tramo; a Floreana, $40. Isabela cobra además un impuesto de ingreso, por confirmar.","Bote-taxi en el muelle: $0,50 ($1 en Isabela).","Hospedaje en Puerto Ayora: ofertas desde unos $33 a $53 por noche; un hotel de 3 estrellas promedia unos $94.","Estado de los sitios tras las inundaciones: A finales de octubre de 2026, lluvias del fenómeno de El Niño provocaron inundaciones en Santa Cruz. El aeropuerto de Baltra suspendió operaciones el 31 de octubre. Al 7 de noviembre el Parque Nacional reabrió los sitios con condiciones seguras, pero Las Grietas, Los Humedales, Puerto Chino y Playa Baquerizo seguían cerrados de forma preventiva. El Inamhi emitió alerta de lluvias fuertes para Santa Cruz, San Cristóbal e Isabela el 12 de noviembre.","Datos menos confiables: Comida por día, transporte local, vuelo del plan normal y tipo de cambio EUR/USD son estimaciones propias. El precio del tour a Santa Fe y del tour terrestre de San Cristóbal proviene de blogs de viajes.","Antes de ofrecer una reserva, se deben confirmar disponibilidad, servicios incluidos, transporte, alimentación, alojamiento, tarifas vigentes, política de cancelación, condiciones de seguridad y el estado de apertura de los sitios de visita."]'::jsonb, 'published') on conflict (id) do update set title = excluded.title, kind = excluded.kind, original_document = excluded.original_document, checked_at = excluded.checked_at, expected_count = excluded.expected_count, notes = excluded.notes, status = excluded.status;
insert into public.knowledge_sources (id, title, kind, original_document, checked_at, expected_count, notes, status) values ('catalogo-amazonia-usuario', '18 inspiraciones de la Amazonía aportadas por el usuario', 'catalog', 'CHULLA_VIDA_3_PAQUETE/catalogos/04_amazonia_usuario.txt', '2026-11-13'::date, 18, '["Estimación aportada por el usuario; no es una tarifa vigente confirmada ni una oferta de CHULLA VIDA.","Aporte de planificación del usuario; precios y tiempos no fueron verificados con prestadores. Las referencias institucionales verifican contexto territorial, no las tarifas ni la disponibilidad.","Algunos nombres, lagunas y rangos se agrupan en el texto. Las fichas separadas conservan esa incertidumbre y no acreditan productos diferentes a la venta."]'::jsonb, 'published') on conflict (id) do update set title = excluded.title, kind = excluded.kind, original_document = excluded.original_document, checked_at = excluded.checked_at, expected_count = excluded.expected_count, notes = excluded.notes, status = excluded.status;
insert into public.knowledge_sources (id, title, kind, original_document, checked_at, expected_count, notes, status) values ('calendario-cultura-viva', 'Calendario editorial semilla de Cultura Viva', 'editorial', 'CHULLA_VIDA_3_PAQUETE/SUPERPROMPT_CHULLA_VIDA_3_0_CLAUDE_CODE.md, sección 5', '2026-11-12'::date, 10, '["Referencia editorial. Las fechas anuales son orientativas hasta la confirmación oficial de cada edición; no acreditan programación, acceso público ni precios."]'::jsonb, 'published') on conflict (id) do update set title = excluded.title, kind = excluded.kind, original_document = excluded.original_document, checked_at = excluded.checked_at, expected_count = excluded.expected_count, notes = excluded.notes, status = excluded.status;
insert into public.knowledge_sources (id, title, kind, original_document, checked_at, expected_count, notes, status) values ('editorial-chulla-vida', 'Contenido editorial de CHULLA VIDA', 'editorial', 'CHULLA_VIDA_3_PAQUETE/SUPERPROMPT_CHULLA_VIDA_3_0_CLAUDE_CODE.md', '2026-11-13'::date, null, '["Preguntas frecuentes y planes: propuesta editorial pendiente de aprobación."]'::jsonb, 'published') on conflict (id) do update set title = excluded.title, kind = excluded.kind, original_document = excluded.original_document, checked_at = excluded.checked_at, expected_count = excluded.expected_count, notes = excluded.notes, status = excluded.status;
