insert into public.events (id, slug, name, local_name, category, region_id, provinces, localities, community_label, usual_months, date_label, description, sensitive, official_url, last_checked_at, status) values ('inti-raymi', 'inti-raymi', 'Inti Raymi', 'Inti Raymi', 'raymi', 'sierra', '["Imbabura","Cañar"]'::jsonb, '["Otavalo","Cotacachi","Ingapirca"]'::jsonb, null, '[6]'::jsonb, 'Junio; cada comunidad define sus días', 'Celebración andina de junio que se vive en Otavalo, Cotacachi e Ingapirca, entre otros lugares. No es una sola fiesta: cada pueblo y comunidad la celebra con sus propias formas, tiempos y significados, y esas diferencias locales merecen conocerse y respetarse.', false, null, '2026-11-12'::date, 'published') on conflict (id) do update set slug = excluded.slug, name = excluded.name, local_name = excluded.local_name, category = excluded.category, region_id = excluded.region_id, provinces = excluded.provinces, localities = excluded.localities, community_label = excluded.community_label, usual_months = excluded.usual_months, date_label = excluded.date_label, description = excluded.description, sensitive = excluded.sensitive, official_url = excluded.official_url, last_checked_at = excluded.last_checked_at;
