insert into public.cultural_protocols (event_id, sort_order, body) values ('inti-raymi', 1, 'Pide permiso antes de fotografiar o grabar a danzantes, músicos y ceremonias.') on conflict (event_id, sort_order) where (event_id is not null) do update set sort_order = excluded.sort_order, body = excluded.body;
