insert into public.cultural_protocols (event_id, sort_order, body) values ('fiesta-chonta', 0, 'El lugar y el momento los define cada comunidad: no hay una fecha pública que reservar.') on conflict (event_id, sort_order) where (event_id is not null) do update set sort_order = excluded.sort_order, body = excluded.body;
insert into public.cultural_protocols (event_id, sort_order, body) values ('fiesta-chonta', 1, 'Asiste solo si la comunidad te invita o te autoriza, y acepta un «no» sin insistir.') on conflict (event_id, sort_order) where (event_id is not null) do update set sort_order = excluded.sort_order, body = excluded.body;
