insert into public.faq_entries (id, category, question, answer, sort_order, source_id, checked_at, status, published_at) values ('que-es-chulla-vida', 'general', '¿Qué es CHULLA VIDA?', 'Una plataforma para descubrir experiencias culturales y de naturaleza en Ecuador junto a anfitriones, comunidades y negocios locales. Por ahora funciona como guía editorial: las fichas son referenciales y todavía no se pueden comprar desde aquí.', 1, 'editorial-chulla-vida', '2026-11-13'::date, 'published', '2026-11-13'::timestamptz) on conflict (id) do update set category = excluded.category, question = excluded.question, answer = excluded.answer, sort_order = excluded.sort_order, source_id = excluded.source_id, checked_at = excluded.checked_at;
insert into public.faq_entries (id, category, question, answer, sort_order, source_id, checked_at, status, published_at) values ('puedo-reservar', 'reservas', '¿Puedo reservar y pagar desde la aplicación?', 'Todavía no. Ninguna ficha del catálogo tiene la reserva habilitada. Se activará únicamente cuando el operador esté verificado, el precio esté confirmado y la pasarela de pagos esté contratada y probada.', 2, 'editorial-chulla-vida', '2026-11-13'::date, 'published', '2026-11-13'::timestamptz) on conflict (id) do update set category = excluded.category, question = excluded.question, answer = excluded.answer, sort_order = excluded.sort_order, source_id = excluded.source_id, checked_at = excluded.checked_at;
insert into public.faq_entries (id, category, question, answer, sort_order, source_id, checked_at, status, published_at) values ('precios-referenciales', 'reservas', '¿Los precios que veo son definitivos?', 'No. Son valores referenciales o propuestos, tomados de los catálogos de origen y mostrados en su moneda original. Pueden cambiar por temporada, operador y tamaño del grupo; confírmalos antes de armar tu presupuesto.', 3, 'editorial-chulla-vida', '2026-11-13'::date, 'published', '2026-11-13'::timestamptz) on conflict (id) do update set category = excluded.category, question = excluded.question, answer = excluded.answer, sort_order = excluded.sort_order, source_id = excluded.source_id, checked_at = excluded.checked_at;
insert into public.faq_entries (id, category, question, answer, sort_order, source_id, checked_at, status, published_at) values ('verificacion-anfitriones', 'confianza', '¿Qué significa que un anfitrión esté verificado?', 'Que una persona del equipo revisó su identidad y su documentación. «Registro turístico oficial verificado» es un distintivo aparte y solo aparece cuando existe evidencia de ese registro. Ninguno de los dos implica un aval del Gobierno. Las fichas importadas de los catálogos todavía no tienen un operador verificado.', 4, 'editorial-chulla-vida', '2026-11-13'::date, 'published', '2026-11-13'::timestamptz) on conflict (id) do update set category = excluded.category, question = excluded.question, answer = excluded.answer, sort_order = excluded.sort_order, source_id = excluded.source_id, checked_at = excluded.checked_at;
insert into public.faq_entries (id, category, question, answer, sort_order, source_id, checked_at, status, published_at) values ('viajar-con-mascota', 'chulla-pet', '¿Puedo viajar con mi mascota?', 'Depende de cada lugar y de cada anfitrión. Si la ficha dice «No verificado», consulta las condiciones antes de ir. No sugerimos ingresar con mascotas a Galápagos ni a áreas protegidas donde la autoridad no lo permite.', 5, 'editorial-chulla-vida', '2026-11-13'::date, 'published', '2026-11-13'::timestamptz) on conflict (id) do update set category = excluded.category, question = excluded.question, answer = excluded.answer, sort_order = excluded.sort_order, source_id = excluded.source_id, checked_at = excluded.checked_at;
insert into public.faq_entries (id, category, question, answer, sort_order, source_id, checked_at, status, published_at) values ('sin-internet', 'offline', '¿Funciona sin internet?', 'Sí, de forma limitada: puedes consultar lo que hayas descargado antes de salir. Sin conexión no se actualizan el clima, los avisos ni la disponibilidad, y MIJIN responde solo con el contenido descargado.', 6, 'editorial-chulla-vida', '2026-11-13'::date, 'published', '2026-11-13'::timestamptz) on conflict (id) do update set category = excluded.category, question = excluded.question, answer = excluded.answer, sort_order = excluded.sort_order, source_id = excluded.source_id, checked_at = excluded.checked_at;
insert into public.faq_entries (id, category, question, answer, sort_order, source_id, checked_at, status, published_at) values ('quien-es-mijin', 'mijin', '¿Quién es MIJIN?', 'Es el asistente de CHULLA VIDA, tu pana de aventuras. Responde con la información del catálogo y de las fuentes que cita; cuando no tiene un dato confirmado, te lo dice en lugar de inventarlo. No reemplaza a las autoridades ni a los servicios de emergencia.', 7, 'editorial-chulla-vida', '2026-11-13'::date, 'published', '2026-11-13'::timestamptz) on conflict (id) do update set category = excluded.category, question = excluded.question, answer = excluded.answer, sort_order = excluded.sort_order, source_id = excluded.source_id, checked_at = excluded.checked_at;
insert into public.faq_entries (id, category, question, answer, sort_order, source_id, checked_at, status, published_at) values ('sellos-pasaporte-guambra', 'pasaporte', '¿Cómo consigo sellos en el Pasaporte Guambra?', 'Puedes anotar tus visitas por tu cuenta; esas quedan como sellos autodeclarados. El sello de «visita verificada» se otorga únicamente después de una validación, por ejemplo una reserva completada con el anfitrión.', 8, 'editorial-chulla-vida', '2026-11-13'::date, 'published', '2026-11-13'::timestamptz) on conflict (id) do update set category = excluded.category, question = excluded.question, answer = excluded.answer, sort_order = excluded.sort_order, source_id = excluded.source_id, checked_at = excluded.checked_at;
insert into public.faq_entries (id, category, question, answer, sort_order, source_id, checked_at, status, published_at) values ('mis-datos-personales', 'privacidad', '¿Qué pasa con mis datos personales?', 'Puedes pedir acceso, corrección o eliminación de tus datos y retirar tus consentimientos desde «Privacidad y cookies». Los textos legales de esta etapa son borradores pendientes de revisión jurídica.', 9, 'editorial-chulla-vida', '2026-11-13'::date, 'published', '2026-11-13'::timestamptz) on conflict (id) do update set category = excluded.category, question = excluded.question, answer = excluded.answer, sort_order = excluded.sort_order, source_id = excluded.source_id, checked_at = excluded.checked_at;
